import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = config.id || 'collection-card-1-label';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const paper = colors.paper ?? '#e8ecf2';
  const surface = colors.surface ?? '#0b0b10';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') || items[0] || {};
  const headlineText = headlineItem.text ?? 'Collection 1';
  const fontSize = headlineItem.typography?.fontSize ?? 39;

  const atlas = config.atlasRegion ?? config.intent?.visualSpec?.atlasRegion ?? {};
  const rect = atlas.rect ?? atlas.sourceRect ?? { x: 0, y: 0, w: 512, h: 320 };
  const atlasW = atlas.size?.width ?? rect.x + rect.w;
  const atlasH = atlas.size?.height ?? rect.y + rect.h;
  const aspect = rect.w / rect.h;
  const uvScaleX = rect.w / atlasW;
  const uvScaleY = rect.h / atlasH;
  const uvOffsetX = rect.x / atlasW;
  const uvOffsetY = rect.y / atlasH;

  const geometry = new THREE.PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false,
    opacity: 0,
  });

  const spriteMesh = new THREE.Mesh(geometry, material);
  spriteMesh.name = 'sprite';
  group.add(spriteMesh);

  const textObj = ctx.fontAtlas.createText(headlineText, {
    fontSize,
    color: paper,
    align: 'center',
  });
  textObj.position.set(0, -0.72, 0.02);
  group.add(textObj);

  let tex = null;
  let disposed = false;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((loadedTex) => {
      if (disposed) {
        loadedTex.dispose();
        return;
      }
      tex = loadedTex;
      tex.colorSpace = ctx.THREE.SRGBColorSpace;

      const mapNode = texture(tex).uv(
        uv().mul(vec2(uvScaleX, uvScaleY)).add(vec2(uvOffsetX, uvOffsetY))
      );
      material.map = mapNode;
      material.opacity = 1;
      material.needsUpdate = true;
    }).catch(() => {
      material.color.set(surface);
      material.opacity = 1;
    });
  } else {
    material.color.set(surface);
    material.opacity = 1;
  }

  group.scale.set(0.95, 0.95, 0.95);
  const tl = gsap.timeline();
  tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.7, ease: 'power4.out' });

  group.userData.update = (camera) => {
    if (camera && spriteMesh) {
      spriteMesh.lookAt(camera.position);
    }
  };

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    disposed = true;
    tl.kill();
    gsap.killTweensOf(group.scale);
    if (tex) tex.dispose();
    geometry.dispose();
    material.dispose();
    textObj.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) {
          o.material.forEach((m) => m.dispose());
        } else {
          o.material.dispose();
        }
      }
    });
  };

  return group;
}
